//| CTradeExcursion                                                   |
//+-------------------------------------------------------------------+
class
CTradeExcursion
  {
public
:
ulong
m_position_id;
// MQL5 position identifier grouping the deals
string
m_symbol;
// symbol this position was traded on
bool
m_is_long;
// true for a long position, false for a short
datetime
m_entry_time;
// server-time open of the position
datetime
m_close_time;
// server-time of the last closing deal
double
m_entry_price;
// price at which the position was opened
double
m_net_profit;
// realized profit + swap + commission
double
m_mae;
// Maximum Adverse Excursion, in price units, always >= 0
double
m_mfe;
// Maximum Favorable Excursion, in price units, always >= 0
double
m_efficiency;
// MFE / (MFE + MAE), meaningful only when m_efficiency_defined
bool
m_efficiency_defined;
// false when the trade showed no tick-level price movement
int
m_tick_count;
// number of ticks used to compute m_mae and m_mfe
CTradeExcursion(
void
);
  };
