Grouping Deals into Closed Positions — PositionHistoryReader.mqh
A single closed position can involve more than one deal: an entry deal that opens it, and one or more closing deals if it was closed in pieces through partial closes. MQL5 groups these together with DEAL_POSITION_ID, and CPositionHistoryReader uses that identifier as a grouping key.
//+------------------------------------------------------------------+
//|                                        PositionHistoryReader.mqh |
//+------------------------------------------------------------------+
#ifndef
POSITIONHISTORYREADER_MQH
#define
POSITIONHISTORYREADER_MQH
#include
"TradeExcursionTypes.mqh"
//+--------------------------------------------------------------------+
//| CPositionHistoryReader                                             |
//+--------------------------------------------------------------------+
class
CPositionHistoryReader
  {
private
:
int
FindPositionIndex(
const
CTradeExcursion &trades[],
int
count,
ulong
position_id)
const
;
void
CopyRecord(CTradeExcursion &dest,
const
CTradeExcursion &src)
const
;
public
:
                     CPositionHistoryReader(
void
);
                    ~CPositionHistoryReader(
void
);
bool
Read(
const
string
symbol,
datetime
from,
datetime
to, CTradeExcursion &trades_out[]);
  };
