//| Constructor                                                      |
//| The reader is stateless between calls, so construction performs  |
//| no work beyond default object creation.                          |
//+------------------------------------------------------------------+
CPositionHistoryReader::CPositionHistoryReader(
void
)
  {
  }
//+------------------------------------------------------------------+
//| Destructor                                                       |
//| No resources are owned by this class, so no cleanup is required. |
//+------------------------------------------------------------------+
CPositionHistoryReader::~CPositionHistoryReader(
void
)
  {
  }
FindPositionIndex() decides whether an incoming deal belongs to a position already seen or needs a new record. It only reads the array, so it stays a safe const method. CopyRecord() supports a later compaction step. It copies one CTradeExcursion into another, field by field, keeping the operation unambiguous.
//+---------------------------------------------------------------------+
//| FindPositionIndex                                                   |
//+---------------------------------------------------------------------+
int
CPositionHistoryReader::FindPositionIndex(
const
CTradeExcursion &trades[],
const
int
count,
const
ulong
position_id)
const
{
for
(
int
i =
0
; i < count; i++)
     {
if
(trades[i].m_position_id == position_id)
return
(i);
     }
return
(-
1
);
  }
//+---------------------------------------------------------------------+
//| CopyRecord                                                          |
//+---------------------------------------------------------------------+
void
CPositionHistoryReader::CopyRecord(CTradeExcursion &dest,
const
CTradeExcursion &src)
const
{
   dest.m_position_id        = src.m_position_id;
   dest.m_symbol             = src.m_symbol;
   dest.m_is_long            = src.m_is_long;
   dest.m_entry_time         = src.m_entry_time;
   dest.m_close_time         = src.m_close_time;
   dest.m_entry_price        = src.m_entry_price;
   dest.m_net_profit         = src.m_net_profit;
   dest.m_mae                = src.m_mae;
   dest.m_mfe                = src.m_mfe;
   dest.m_efficiency         = src.m_efficiency;
   dest.m_efficiency_defined = src.m_efficiency_defined;
   dest.m_tick_count         = src.m_tick_count;
  }
Read() selects the terminal's history cache for the requested range and iterates over all deals for the requested symbol. An entry deal, DEAL_ENTRY_IN, supplies open time, open price, and direction. A closing deal, DEAL_ENTRY_OUT or DEAL_ENTRY_INOUT, supplies a close time, and the latest closing deal seen wins, so a position closed through several partial closes ends up with the time of its final close. Net profit accumulates profit, swap, and commission across every deal belonging to the position.
Once every deal has been folded in, Read() compacts the array. Only positions with a valid entry time and a close time strictly after it survive. A position opened before the requested range, or still open at the end of it, is only partially visible and gets dropped rather than scored on an incomplete price path.
//+------------------------------------------------------------------------+
//| Read                                                                   |
//+------------------------------------------------------------------------+
bool
CPositionHistoryReader::Read(
const
string
symbol,
datetime
from,
datetime
to,CTradeExcursion &trades_out[])
  {
//--- start from an empty output buffer regardless of any prior contents
::
ArrayResize
(trades_out,
0
);
//--- ask the terminal to build the history cache for the requested interval
if
(!::
HistorySelect
(from, to))
     {
      ::
Print
(
"CPositionHistoryReader: HistorySelect failed for the requested range."
);
return
(
false
);
     }
//--- walk every deal available in the freshly selected history cache
int
total_deals = ::
HistoryDealsTotal
();
for
(
int
i =
0
; i < total_deals; i++)
     {
ulong
ticket = ::
HistoryDealGetTicket
(i);
if
(ticket ==
0
)
continue
;
//--- only deals on the requested symbol contribute to this analysis
string
deal_symbol = ::
HistoryDealGetString
(ticket,
DEAL_SYMBOL
);
if
(deal_symbol != symbol)
continue
;
ulong
position_id = (
ulong
)::
HistoryDealGetInteger
(ticket,
DEAL_POSITION_ID
);
long
entry_type   = ::
HistoryDealGetInteger
(ticket,
DEAL_ENTRY
);
double
deal_profit = ::
HistoryDealGetDouble
(ticket,
DEAL_PROFIT
)
                           + ::
HistoryDealGetDouble
(ticket,
DEAL_SWAP
)
                           + ::
HistoryDealGetDouble
(ticket,
DEAL_COMMISSION
);
//--- find or create the working record for this position
int
index = FindPositionIndex(trades_out, ::
ArraySize
(trades_out), position_id);
if
(index <
0
)
        {
         index = ::
ArraySize
(trades_out);
         ::
ArrayResize
(trades_out, index +
1
);
         trades_out[index].m_position_id = position_id;
         trades_out[index].m_symbol      = symbol;
        }
      trades_out[index].m_net_profit += deal_profit;
if
(entry_type ==
DEAL_ENTRY_IN
)
        {
//--- the entry deal supplies open time, open price, and direction
trades_out[index].m_entry_time  = (
datetime
)::
HistoryDealGetInteger
(ticket,
DEAL_TIME
);
         trades_out[index].m_entry_price = ::
HistoryDealGetDouble
(ticket,
DEAL_PRICE
);
long
deal_type = ::
HistoryDealGetInteger
(ticket,
DEAL_TYPE
);
         trades_out[index].m_is_long = (deal_type ==
DEAL_TYPE_BUY
);
        }
else
if
(entry_type ==
DEAL_ENTRY_OUT
|| entry_type ==
DEAL_ENTRY_INOUT
)
           {
//--- the latest closing deal determines the final close time
datetime
candidate_close = (
datetime
)::
HistoryDealGetInteger
(ticket,
DEAL_TIME
);
if
(candidate_close > trades_out[index].m_close_time)
               trades_out[index].m_close_time = candidate_close;
           }
     }
//--- compact the array, keeping only positions with a full entry-to-close path
int
write_index =
0
;
int
read_count   = ::
ArraySize
(trades_out);
for
(
int
read_index =
0
; read_index < read_count; read_index++)
     {
bool
is_complete = trades_out[read_index].m_entry_time >
0
&& trades_out[read_index].m_close_time > trades_out[read_index].m_entry_time;
if
(is_complete)
        {
if
(write_index != read_index)
            CopyRecord(trades_out[write_index], trades_out[read_index]);
         write_index++;
        }
     }
   ::
ArrayResize
(trades_out, write_index);
return
(
true
);
  }
Computing MAE, MFE, and Entry Efficiency from Ticks — ExcursionCalculator.mqh
MqlTick
bid and ask are the raw materials this stage uses. CExcursionCalculator keeps retrieval separate from arithmetic, so the arithmetic can be tested with a synthetic tick array and no dependency on a live account.
//+------------------------------------------------------------------+
//|                                          ExcursionCalculator.mqh |
//+------------------------------------------------------------------+
#ifndef
EXCURSIONCALCULATOR_MQH
#define
EXCURSIONCALCULATOR_MQH
#include
"TradeExcursionTypes.mqh"
//+---------------------------------------------------------------------+
//| CExcursionCalculator                                                |
//+---------------------------------------------------------------------+
class
CExcursionCalculator
  {
public
:
                     CExcursionCalculator(
void
);
                    ~CExcursionCalculator(
void
);
bool
ReadTicks(
const
string
symbol,
datetime
from,
datetime
to,
MqlTick
&ticks_out[])
const
;
bool
ComputeExcursionFromTicks(
const
MqlTick
&ticks[],
int
count,
double
entry_price,
bool
is_long,
double
&mae_out,
double
&mfe_out)
const
;
bool
ComputeEfficiency(
double
mae,
double
mfe,
double
&efficiency_out)
const
;
bool
Compute(CTradeExcursion &trade)
const
;
  };
//+------------------------------------------------------------------+
//| Constructor                                                      |
//| The calculator holds no state between calls, so construction     |
//| performs no work beyond default object creation.                 |
//+------------------------------------------------------------------+
CExcursionCalculator::CExcursionCalculator(
void
)
  {
  }
//+------------------------------------------------------------------+
//| Destructor                                                       |
//| No resources are owned by this class, so no cleanup is required. |
//+------------------------------------------------------------------+
CExcursionCalculator::~CExcursionCalculator(
void
)
  {
  }
ReadTicks() requests every tick for a symbol between a position's entry and close time, using
CopyTicksRange
, which expects both time boundaries in milliseconds rather than the whole-second datetime values used elsewhere. Returning true with an empty result array is valid. Terminals typically retain tick history for a much shorter period than deal history, so older positions may legitimately have no ticks available. Only a negative result from CopyTicksRange counts as a failure.
//+-------------------------------------------------------------------------+
//| ReadTicks                                                               |
//+-------------------------------------------------------------------------+
bool
CExcursionCalculator::ReadTicks(
const
string
symbol,
datetime
from,
datetime
to,
MqlTick
&ticks_out[])
const
{
ulong
from_msc = (
ulong
)from *
1000
;
ulong
to_msc   = (
ulong
)to   *
1000
;
int
copied = ::
CopyTicksRange
(symbol, ticks_out,
COPY_TICKS_ALL
, from_msc, to_msc);
if
(copied <
0
)
     {
      ::
Print
(
"CExcursionCalculator: CopyTicksRange failed for "
, symbol);
return
(
false
);
     }
return
(
true
);
  }
ComputeExcursionFromTicks() walks that tick array and tracks the largest favorable and largest adverse move away from the entry price. For a long position, the price it would actually close at is the bid, so favorable movement is the bid rising above entry, and adverse movement is the bid falling below it. For a short position the closing price is the ask, and the direction mirrors. Both figures start at zero and only grow, so a position that never moved favorably reports an MFE of exactly zero rather than a negative number.
//+--------------------------------------------------------------------------+
//| ComputeExcursionFromTicks                                                |
//+--------------------------------------------------------------------------+
bool
CExcursionCalculator::ComputeExcursionFromTicks(
const
MqlTick
&ticks[],
const
int
count,
const
double
entry_price,
const
bool
is_long,
double
&mae_out,
double
&mfe_out)
const
{
   mae_out =
0.0
;
   mfe_out =
0.0
;
if
(count <=
0
)
return
(
false
);
//--- walk every tick and track the largest favorable and adverse distance
for
(
int
i =
0
; i < count; i++)
     {
double
reference_price = is_long ? ticks[i].bid : ticks[i].ask;
double
excursion = is_long ? (reference_price - entry_price) : (entry_price - reference_price);
if
(excursion > mfe_out)
         mfe_out = excursion;
if
(-excursion > mae_out)
         mae_out = -excursion;
     }
return
(
true
);
  }
ComputeEfficiency() turns that pair into a single ratio. A value near 1.0 means the trade moved almost entirely in its favor before closing; near 0.0 means the opposite. One case needs its own branch: a trade whose MAE and MFE are both exactly zero, meaning no tick-level movement was observed at all. That ratio is 0/0, so the method reports it as undefined via its return value. This avoids silently returning 0.0, which could be misread as a computed result.
//+------------------------------------------------------------------------+
//| ComputeEfficiency                                                      |
//+------------------------------------------------------------------------+
bool
CExcursionCalculator::ComputeEfficiency(
const
double
mae,
const
double
mfe,
double
&efficiency_out)
const
{
if
(mae + mfe ==
0.0
)
     {
      efficiency_out =
0.0
;
return
(
false
);
     }
   efficiency_out = mfe / (mfe + mae);
return
(
true
);
  }
Compute() ties the three previous methods together for one trade. It reads the ticks spanning entry-to-close, derives MAE and MFE, then derives efficiency. The trade's m_tick_count field is set regardless of outcome, so a caller can distinguish "zero ticks available" from any later computed result just by inspecting the record. This method writes into the trade passed by reference, but never touches its own member state, so it stays const.
//+-----------------------------------------------------------------------------+
//| Compute                                                                     |
//+-----------------------------------------------------------------------------+
bool
CExcursionCalculator::Compute(CTradeExcursion &trade)
const
{
MqlTick
ticks[];
if
(!ReadTicks(trade.m_symbol, trade.m_entry_time, trade.m_close_time, ticks))
return
(
false
);
int
tick_total = ::
ArraySize
(ticks);
   trade.m_tick_count = tick_total;
double
mae =
0.0
, mfe =
0.0
;
if
(!ComputeExcursionFromTicks(ticks, tick_total, trade.m_entry_price, trade.m_is_long, mae, mfe))
return
(
false
);
   trade.m_mae = mae;
   trade.m_mfe = mfe;
double
efficiency =
0.0
;
   trade.m_efficiency_defined = ComputeEfficiency(mae, mfe, efficiency);
   trade.m_efficiency         = efficiency;
return
(
true
);
  }
Reducing Trades to Aggregate Statistics — EfficiencyStatistics.mqh
CEfficiencyStatistics turns an array of trade records into three figures a histogram needs: a mean efficiency, a set of bin counts, and a win/loss/breakeven split. Every method is a pure function over plain data.
//+------------------------------------------------------------------+
//|                                         EfficiencyStatistics.mqh |
//+------------------------------------------------------------------+
#ifndef
EFFICIENCYSTATISTICS_MQH
#define
EFFICIENCYSTATISTICS_MQH
#include
"TradeExcursionTypes.mqh"
//+---------------------------------------------------------------------+
//| CEfficiencyStatistics                                               |
//+---------------------------------------------------------------------+
class
CEfficiencyStatistics
  {
public
:
                     CEfficiencyStatistics(
void
);
                    ~CEfficiencyStatistics(
void
);
bool
ComputeMeanEfficiency(
const
CTradeExcursion &trades[],
int
count,
double
&mean_out)
const
;
void
ComputeHistogramBins(
const
CTradeExcursion &trades[],
int
count,
int
bin_count,
int
&bins_out[])
const
;
void
ComputeWinLossCounts(
const
CTradeExcursion &trades[],
int
count,
int
&win_count,
int
&loss_count,
int
&breakeven_count)
const
;
  };
//+------------------------------------------------------------------+
//| Constructor                                                      |
//| The statistics helper holds no state between calls, so           |
//| construction performs no work beyond default object creation.    |
//+------------------------------------------------------------------+
CEfficiencyStatistics::CEfficiencyStatistics(
void
)
  {
  }
//+------------------------------------------------------------------+
//| Destructor                                                       |
//| No resources are owned by this class, so no cleanup is required. |
//+------------------------------------------------------------------+
CEfficiencyStatistics::~CEfficiencyStatistics(
void
)
  {
  }
ComputeMeanEfficiency() averages efficiency only across trades whose value is defined, skipping any trade with no tick data or no observed movement. If no trade qualifies, it reports failure rather than a mean of zero, which could be mistaken for a genuinely poor average.
//+------------------------------------------------------------------------+
//| ComputeMeanEfficiency                                                  |
//+------------------------------------------------------------------------+
bool
CEfficiencyStatistics::ComputeMeanEfficiency(
const
CTradeExcursion &trades[],
const
int
count,
double
&mean_out)
const
{
double
sum =
0.0
;
int
defined_count =
0
;
for
(
int
i =
0
; i < count; i++)
     {
if
(trades[i].m_efficiency_defined)
        {
         sum += trades[i].m_efficiency;
         defined_count++;
        }
     }
if
(defined_count <=
0
)
     {
      mean_out =
0.0
;
return
(
false
);
     }
   mean_out = sum / defined_count;
return
(
true
);
  }
ComputeHistogramBins() distributes each trade's efficiency into equal-width bins spanning 0.0 to 1.0. A trade with no defined efficiency is skipped, rather than folded into bin zero, which would overweight the low end. One boundary needs explicit handling: an efficiency of exactly 1.0, multiplied by the bin count, lands exactly one position past the last valid bin, so that result is clamped back into the final bin.
//+---------------------------------------------------------------------------+
//| ComputeHistogramBins                                                      |
//+---------------------------------------------------------------------------+
void
CEfficiencyStatistics::ComputeHistogramBins(
const
CTradeExcursion &trades[],
const
int
count,
const
int
bin_count,
int
&bins_out[])
const
{
   ::
ArrayResize
(bins_out, bin_count);
   ::
ArrayInitialize
(bins_out,
0
);
for
(
int
i =
0
; i < count; i++)
     {
if
(!trades[i].m_efficiency_defined)
continue
;
int
bin_index = (
int
)(trades[i].m_efficiency * bin_count);
//--- an efficiency of exactly 1.0 must land in the last bin, not one past it
if
(bin_index >= bin_count)
         bin_index = bin_count -
1
;
if
(bin_index <
0
)
         bin_index =
0
;
      bins_out[bin_index]++;
     }
  }
ComputeWinLossCounts() classifies every trade by the sign of its net profit. A net profit of exactly zero counts as breakeven, its own category, never folded into either the win or the loss count.
//+-----------------------------------------------------------------------+
//| ComputeWinLossCounts                                                  |
//+-----------------------------------------------------------------------+
void
CEfficiencyStatistics::ComputeWinLossCounts(
const
CTradeExcursion &trades[],
const
int
count,
int
&win_count,
int
&loss_count,
int
&breakeven_count)
const
{
   win_count       =
0
;
   loss_count      =
0
;
   breakeven_count =
0
;
for
(
int
i =
0
; i < count; i++)
     {
if
(trades[i].m_net_profit >
0.0
)
         win_count++;
else
if
(trades[i].m_net_profit <
0.0
)
            loss_count++;
else
breakeven_count++;
     }
  }
Rendering the MAE/MFE Scatter Plot with CCanvas — ExcursionScatterChart.mqh
CExcursionScatterChart owns a
CCanvas
instance and plots MAE on the horizontal axis against MFE on the vertical axis, one point per trade. The constructor stores the object name and default margins; the canvas itself is created lazily on the first call to Draw(). The destructor is intentionally empty, since the rendered panel needs to survive after the script that drew it finishes. Clear() is the one explicit, caller-driven way to tear the panel down.
//+------------------------------------------------------------------+
//|                                        ExcursionScatterChart.mqh |
//+------------------------------------------------------------------+
#ifndef
EXCURSIONSCATTERCHART_MQH
#define
EXCURSIONSCATTERCHART_MQH
#include
<Canvas\Canvas.mqh>
#include
"TradeExcursionTypes.mqh"
//--- palette used by the scatter chart, kept at file scope
const
color
EXCUR_COLOR_BACKGROUND =
clrWhite
;
const
color
EXCUR_COLOR_AXIS       =
clrBlack
;
const
color
EXCUR_COLOR_TEXT       =
clrBlack
;
const
color
EXCUR_COLOR_DIAGONAL   =
C'150,150,150'
;
const
color
EXCUR_COLOR_WIN        =
C'0,140,60'
;
const
color
EXCUR_COLOR_LOSS       =
C'190,30,30'
;
const
color
EXCUR_COLOR_BREAKEVEN  =
C'140,140,140'
;
